<?php require_once __DIR__.'/inc/config.php'; require_once __DIR__.'/inc/auth.php'; require_admin(); $message=''; if($_SERVER['REQUEST_METHOD']==='POST'){ if(!verify_admin_password($_POST['old_pass']??''))$message='Old password is incorrect.'; elseif(($_POST['new_pass']??'')!==($_POST['confirm_pass']??''))$message='Passwords do not match.'; elseif(strlen($_POST['new_pass'])<6)$message='Use at least 6 characters.'; else { file_put_contents(__DIR__.'/inc/pass.json',json_encode(['hash'=>password_hash($_POST['new_pass'],PASSWORD_DEFAULT)],JSON_PRETTY_PRINT)); $message='Password changed successfully.'; }} admin_header('Change Password'); ?><section class="admin-panel"><h2>Change admin password</h2><?php if($message):?><p class="success-message"><?=e($message)?></p><?php endif;?><form class="admin-form" method="post"><label>Current password<input type="password" name="old_pass" required></label><label>New password<input type="password" name="new_pass" required></label><label>Confirm password<input type="password" name="confirm_pass" required></label><button class="btn">Change password</button></form><p><a href="admin.php">Back to orders</a></p></section><?php admin_footer();?>
